def parse_nested_parens(paren_string: str) -> List[int]:
    max_levels = []
    groups = paren_string.split()
    for group in groups:
        level = 0
        for char in group:
            if char == "(":
                level += 1
            elif char == ")":
                level -= 1
        max_levels.append(level)
    return max_levels

